    // まず通常条件で全テンプレートを比較し、外れたセルだけ追加条件で再比較する。
    const offsets=[0,2,4,6,8,10,12,14];
    const makeSigs=threshold=>offsets.map(offset=>inkMask(image,[x+4,y+offset,w-8,20],2,2,threshold));
